def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def fibonacci():
    """Generator for Fibonacci numbers."""
    a, b = 0, 1
    while True:
        yield b
        a, b = b, a + b

def prime_fib(n: int) -> int:
    """Return the n-th Fibonacci number that is also a prime."""
    fib_gen = fibonacci()
    for _ in range(n):
        fib_number = next(fib_gen)
        if is_prime(fib_number):
            return fib_number

# Testing
if __name__ == "__main__":
    print(prime_fib(1))  # 2
    print(prime_fib(2))  # 3
    print(prime_fib(3))  # 5
    print(prime_fib(4))  # 13
    print(prime_fib(5))  # 89
